Definition tga_musl_cells (m : mem) : Prop :=
  rw_cells asegs m g_tls_index [C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 0xfffffffffffff800)]
  /\ rw_cells asegs m g_dtv_ptr [C8 (Z_to_bv 64 g_dtv)]
