  /\ rw_cells asegs m g_got_dtls_off [C8 (Z_to_bv 64 24)]   (* [comment removed for export] *)
  /\ rw_cells asegs m g_tls_dtls [C8 (Z_to_bv 64 DTV)]
  /\ rw_cells asegs m (DTV + 24) [C8 (Z_to_bv 64 dtvbeg)].

